package com.cognia.api.adapter.out.persistence;
import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface ActivityJpaRepository extends JpaRepository<ActivityJpaEntity,UUID> { @Query("select a from ActivityJpaEntity a where a.conceptId=:concept and a.usage='PRACTICA' and a.active=true and (:difficulty is null or a.difficulty=:difficulty) order by a.difficulty,a.code") List<ActivityJpaEntity> findPractice(@Param("concept") UUID concept,@Param("difficulty") Integer difficulty); @Query("select a from ActivityJpaEntity a where a.conceptId=:concept and a.usage='PRACTICA' and a.active=true and a.difficulty<=:difficulty order by a.difficulty,a.code") List<ActivityJpaEntity> findPracticeAtMost(@Param("concept") UUID concept,@Param("difficulty") Integer difficulty); @Query("select a from ActivityJpaEntity a, ConceptJpaEntity c where a.conceptId=c.id and c.subjectId=:subject and a.usage='DIAGNOSTICO' and a.active=true order by a.difficulty,a.code") List<ActivityJpaEntity> findDiagnostic(@Param("subject") UUID subject); @Query("select a from ActivityJpaEntity a where a.conceptId=:concept and a.usage='EVALUACION_CORTA' and a.active=true order by a.difficulty,a.code") List<ActivityJpaEntity> findShortEvaluation(@Param("concept") UUID concept); }
